def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 6:
                for dr, color in ((-1, 4), (0, 0), (1, 4)):
                    if 0 <= r + dr < len(grid):
                        out[r + dr][c] = color
    return out
